/** Persisted order record. */
export interface Order {
  id: string;
  total: number;
}

/** Data access contract used by {@link loadOrders}. */
export interface OrderStore {
  /**
   * Looks up orders by identifier in a single query.
   *
   * @param ids - Order identifiers to resolve.
   * @returns The matching orders, in unspecified order. Unknown identifiers are omitted.
   */
  findByIds(ids: readonly string[]): Promise<Order[]>;
}

/**
 * Loads orders by identifier while preserving the requested order.
 *
 * @param store - Order data store.
 * @param ids - Order identifiers in the desired output order.
 * @returns The resolved orders.
 * @throws Error when an identifier does not resolve.
 * @remarks Issues one store query per call regardless of the number of identifiers.
 */
export async function loadOrders(store: OrderStore, ids: string[]): Promise<Order[]> {
  if (ids.length === 0) {
    return [];
  }

  const storedOrders = await store.findByIds(ids);
  const ordersById = new Map(storedOrders.map((order) => [order.id, order] as const));

  return ids.map((id) => {
    const order = ordersById.get(id);
    if (!order) {
      throw new Error(`order not found: ${id}`);
    }
    return order;
  });
}

