test("loads orders in order", async () => {
  const store: OrderStore = {
    async findByIds(ids) {
      return ids.map((id) => ({ id, total: 1 }));
    },
  };
  const orders = await loadOrders(store, ["a", "b"]);
  assert.deepEqual(orders.map((o) => o.id), ["a", "b"]);
});

test("issues one store query per load request", async () => {
  let queryCount = 0;
  const store: OrderStore = {
    async findByIds(ids) {
      queryCount += 1;
      return ids.map((id) => ({ id, total: 1 }));
    },
  };

  await loadOrders(store, ["a", "b", "c"]);

  assert.equal(queryCount, 1);
});

test("preserves requested order when the store returns results out of order", async () => {
  const store: OrderStore = {
    async findByIds(ids) {
      return [...ids].reverse().map((id) => ({ id, total: 1 }));
    },
  };

  const orders = await loadOrders(store, ["a", "b", "c"]);

  assert.deepEqual(orders.map((o) => o.id), ["a", "b", "c"]);
});

test("reports the first missing identifier in request order", async () => {
  const store: OrderStore = {
    async findByIds(ids) {
      return ids.filter((id) => id === "a").map((id) => ({ id, total: 1 }));
    },
  };

  await assert.rejects(loadOrders(store, ["a", "b", "c"]), /order not found: b/);
});

